import{_ as o,o as t,c as r,a5 as i}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"接口文档","description":"","frontmatter":{"title":"接口文档","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Spring","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/B-接口开发/后端接口开发入门/接口文档.md","filePath":"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/B-接口开发/后端接口开发入门/接口文档.md"}'),c={name:"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/B-接口开发/后端接口开发入门/接口文档.md"};function a(p,e,l,d,n,s){return t(),r("div",null,[...e[0]||(e[0]=[i('<div><p>==推荐使用== <code>springdoc-openapi</code> ==的理由如下：==</p><ul><li><code>springdoc-openapi</code> ==是== <code>spring</code> ==官方出品，与== <code>springboot</code> ==兼容更好（==<code>springfox</code> ==兼容有坑）==</li><li><code>springdoc-openapi</code> ==社区更活跃，==<code>springfox</code> ==已经== <code>2</code> ==年没更新了==</li><li><code>springdoc-openapi</code> ==的注解更接近== <code>OpenAPI 3</code> ==规范==</li></ul><p>使用，<code>pom.xml</code>中添加依赖：</p><ul><li>&lt;dependency&gt;</li><li>&lt;groupId&gt;org.springdoc&lt;/groupId&gt;</li><li>&lt;artifactId&gt;springdoc-openapi-ui&lt;/artifactId&gt;</li><li>&lt;version&gt;1.6.11&lt;/version&gt;</li><li>&lt;/dependency&gt;</li></ul><p>实测发现可配可不配：然后在 <code>Config</code> 中配置基本的描述信息，如下：</p><p>@Configuration public class OpenApiConfig { @Bean public OpenAPI springOpenAPI() { return new OpenAPI() .info(new Info() .title(&quot;SpringDoc API Test&quot;) .description(&quot;SpringDoc Simple Application Test&quot;) .version(&quot;0.0.1&quot;)); } } 接下来在 <code>Controller</code> 中使用注解标记文本，如下：</p><p>@RestController(value = &quot;/clients&quot;) @Tag(name = &quot;/clients&quot;) public class ClientsRestController { @Operation(summary = &quot;This method is used to get the clients.&quot;) @GetMapping public List&lt;String&gt; getClients() { return Arrays.asList(&quot;First Client&quot;, &quot;Second Client&quot;); } } 最后 <code>Application.java</code> 启动应用后，输入默认地址：<code>http://localhost:8081/swagger-ui/index.html</code> 即可看到文档<code>;</code></p><p>这将自动将<code>swagger-ui</code>部署到<code>spring-boot</code>应用程序： ==文档将以==<code>HTML</code>==格式提供，使用官方==<code>swagger-ui jar</code></p><ul><li><code>Swagger UI</code>==页面地址：==</li></ul><p><a href="http://server" target="_blank" rel="noreferrer">http://server</a>:port/context-path/swagger-ui.html</p><ul><li><code>OpenAPI</code>==描述可以在以下==<code>json</code>==格式的==<code>url</code>==中看到：==</li></ul><p><a href="http://server" target="_blank" rel="noreferrer">http://server</a>:port/context-path/v3/api-docs</p><ul><li><code>yaml</code>格式文档地址：</li></ul><p><a href="http://server" target="_blank" rel="noreferrer">http://server</a>:port/context-path/v3/api-docs.yaml 其中：</p><ul><li><code>server: The server name or IP</code></li><li><code>port: The server port</code></li><li><code>context-path: The context path of the application</code></li></ul><p>对于<code>HTML</code>格式<code>swagger</code>文档的自定义路径，可以在<code>application.yml</code>中配置：</p><ul><li><h1 id="swagger-ui-custom-path" tabindex="-1">swagger-ui custom path <a class="header-anchor" href="#swagger-ui-custom-path" aria-label="Permalink to &quot;swagger-ui custom path&quot;">​</a></h1></li><li>springdoc.swagger-ui.path=/swagger-ui.html</li></ul><p>版本配置<code>Swagger UI</code></p><ul><li><code>swagger</code>官方属性的支持可在<code>springdoc-openapi</code>上获得。看官方文档：<a href="https://swagger.io/docs/open-source-tools/swagger-ui/usage/configuration/" target="_blank" rel="noreferrer">Swagger Documentation</a></li><li>您可以在文档中使用与<code>Spring Boot</code>属性相同的<code>swagger</code>属性。</li><li>所有这些属性都应该用下面的前缀来声明<code>: springdoc.swagger-ui</code></li></ul></div>',1)])])}const h=o(c,[["render",a]]);export{u as __pageData,h as default};
